## Contract Source
```solidity
pragma solidity ^0.4.19;

contract PrivateDeposit
{
mapping (address => uint) public balances;

uint public MinDeposit = 1 ether;
address public owner;

Log TransferLog;

modifier onlyOwner() {
require(tx.origin == owner);
_;
}

function PrivateDeposit()
{
owner = msg.sender;
TransferLog = new Log();
}

function setLog(address _lib) onlyOwner
{
TransferLog = Log(_lib);
}

function Deposit()
public
payable
{
if(msg.value >= MinDeposit)
{
balances[msg.sender]+=msg.value;
TransferLog.AddMessage(msg.sender,msg.value,"Deposit");
}
}

function CashOut(uint _am)
{
if(_am<=balances[msg.sender])
{

if(msg.sender.call.value(_am)())
{
balances[msg.sender]-=_am;
TransferLog.AddMessage(msg.sender,_am,"CashOut");
}
}
}

function() public payable{}

}

contract Log
{

struct Message
{
address Sender;
string Data;
uint Val;
uint Time;
}

Message[] public History;

Message LastMsg;

function AddMessage(address _adr,uint _val,string _data)
public
{
LastMsg.Sender = _adr;
LastMsg.Time = now;
LastMsg.Val = _val;
LastMsg.Data = _data;
History.push(LastMsg);
}
}
```

## Fuzzing task — strategy: logic_error_probe

**Objective:** Build a transaction sequence in which the attacker-controlled address (attacker_address) ends up with more total value (native coin + tokens) than it spent — i.e. extract funds from the target or break a value invariant in the attacker's favor. Use at most 12 calls per sequence.

**Goal:** Find broken-invariant and faulty-accounting logic errors.

